import assert from 'node:assert/strict';
import test from 'node:test';
import { createBalanceClient } from './src/client.mjs';
import { singleFlight } from './src/pending.mjs';
import { resolveBalance } from './src/resolve.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return { promise, resolve, reject };
}

test('a pending lookup is shared for one ordered pair and fulfillment permits a reload', async () => {
  const firstLoad = deferred();
  const calls = [];
  const get = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return calls.length === 1 ? firstLoad.promise : { balanceMinor: 22, currency: 'EUR' };
  });

  const first = get('tenant', 'account');
  const same = get('tenant', 'account');
  assert.ok(first instanceof Promise);
  assert.strictEqual(same, first);
  await Promise.resolve();
  assert.deepEqual(calls, [['tenant', 'account']]);

  firstLoad.resolve({ balanceMinor: 11, currency: 'EUR' });
  assert.deepEqual(await first, { balanceMinor: 11, currency: 'EUR' });
  const later = get('tenant', 'account');
  assert.notStrictEqual(later, first);
  assert.deepEqual(await later, { balanceMinor: 22, currency: 'EUR' });
  assert.deepEqual(calls, [['tenant', 'account'], ['tenant', 'account']]);
});

test('tenant, account, and delimiter boundaries keep pending lookups independent', async () => {
  const calls = [];
  const get = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return { balanceMinor: calls.length, currency: 'JPY' };
  });

  const requests = [
    get('tenant-a', 'shared'),
    get('tenant-b', 'shared'),
    get('a:b', 'c'),
    get('a', 'b:c'),
    get('tenant-a', 'other'),
  ];
  assert.equal(new Set(requests).size, requests.length);
  assert.deepEqual((await Promise.all(requests)).map(value => value.balanceMinor), [1, 2, 3, 4, 5]);
  assert.deepEqual(calls, [
    ['tenant-a', 'shared'],
    ['tenant-b', 'shared'],
    ['a:b', 'c'],
    ['a', 'b:c'],
    ['tenant-a', 'other'],
  ]);
});

test('synchronous throws reject the shared Promise and permit a retry', async () => {
  const failure = new Error('load failed');
  let calls = 0;
  const get = createBalanceClient(() => {
    if (++calls === 1) throw failure;
    return { balanceMinor: 0, currency: 'GBP' };
  });

  const first = get('tenant', 'account');
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('tenant', 'account'), first);
  await assert.rejects(first, error => error === failure);
  assert.deepEqual(await get('tenant', 'account'), { balanceMinor: 0, currency: 'GBP' });
  assert.equal(calls, 2);
});

test('asynchronous rejection reaches callers and clears the pending lookup', async () => {
  const firstLoad = deferred();
  const failure = new Error('service failed');
  let calls = 0;
  const get = createBalanceClient(() => ++calls === 1 ? firstLoad.promise : { balanceMinor: -9, currency: 'CHF' });

  const first = get('tenant', 'account');
  assert.strictEqual(get('tenant', 'account'), first);
  firstLoad.reject(failure);
  await assert.rejects(first, error => error === failure);
  assert.deepEqual(await get('tenant', 'account'), { balanceMinor: -9, currency: 'CHF' });
  assert.equal(calls, 2);
  await new Promise(resolve => setImmediate(resolve));
});

test('the pending Promise is registered before a reentrant load runs', async () => {
  let inner;
  const get = createBalanceClient((tenant, account) => {
    inner = get(tenant, account);
    return { balanceMinor: 1, currency: 'USD' };
  });

  const outer = get('tenant', 'account');
  await outer;
  assert.strictEqual(inner, outer);
});

test('singleFlight remains exported and shares only active work by key', async () => {
  let calls = 0;
  const run = singleFlight(value => {
    calls++;
    return value;
  });
  const first = run('key', 5);
  assert.strictEqual(run('key', 9), first);
  assert.equal(await first, 5);
  assert.equal(await run('key', 9), 9);
  assert.equal(calls, 2);
});

test('resolveBalance preserves minor units, currency, and original identifiers', async () => {
  const cases = [
    { balanceMinor: 0, currency: 'EUR' },
    { balanceMinor: -17, currency: 'CHF' },
    { balanceMinor: 9_007_199_254_740_991, currency: 'JPY' },
