import assert from 'node:assert/strict';
import test from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

test('the same ordered pair shares one pending promise, then reloads', async () => {
  let calls = 0;
  let finish;
  const get = createBalanceClient(() => {
    calls++;
    return new Promise(resolve => { finish = resolve; });
  });

  const first = get('tenant', 'account');
  const concurrent = get('tenant', 'account');
  assert.strictEqual(first, concurrent);
  await Promise.resolve();
  assert.equal(calls, 1);

  finish({balanceMinor: 12, currency: 'EUR'});
  assert.deepEqual(await first, {balanceMinor: 12, currency: 'EUR'});

  const later = get('tenant', 'account');
  assert.notStrictEqual(later, first);
  await Promise.resolve();
  assert.equal(calls, 2);
  finish({balanceMinor: 13, currency: 'EUR'});
  assert.equal((await later).balanceMinor, 13);
});

test('different ordered pairs stay independent and pass original strings to load', async () => {
  const calls = [];
  const get = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return {balanceMinor: calls.length, currency: 'USD'};
  });

  const requests = [
    get('tenant:one', 'account'),
    get('tenant:two', 'account'),
    get('tenant:one', 'other'),
    get('a:b', 'c'),
    get('a', 'b:c'),
    get('account', 'tenant:one'),
  ];
  for (let i = 0; i < requests.length; i++) {
    for (let j = i + 1; j < requests.length; j++) {
      assert.notStrictEqual(requests[i], requests[j]);
    }
  }

  assert.deepEqual(await Promise.all(requests),
    [1, 2, 3, 4, 5, 6].map(balanceMinor => ({balanceMinor, currency: 'USD'})));
  assert.deepEqual(calls, [
    ['tenant:one', 'account'],
    ['tenant:two', 'account'],
    ['tenant:one', 'other'],
    ['a:b', 'c'],
    ['a', 'b:c'],
    ['account', 'tenant:one'],
  ]);
});

test('synchronous throws become shared rejections and a later call retries', async () => {
  const failure = new Error('loader failed');
  let calls = 0;
  const get = createBalanceClient(() => {
    calls++;
    throw failure;
  });

  const first = get('tenant', 'account');
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('tenant', 'account'), first);
  await assert.rejects(first, error => error === failure);
  assert.equal(calls, 1);

  const retry = get('tenant', 'account');
  assert.notStrictEqual(retry, first);
  await assert.rejects(retry, error => error === failure);
  assert.equal(calls, 2);
});

test('asynchronous rejection clears pending and permits retry', async () => {
  const failure = new Error('remote failure');
  let calls = 0;
  const get = singleFlight(() => {
    calls++;
    return calls === 1 ? Promise.reject(failure) : Promise.resolve('recovered');
  });

  const first = get('key');
  assert.strictEqual(get('key'), first);
  await assert.rejects(first, error => error === failure);
  const retry = get('key');
  assert.notStrictEqual(retry, first);
  assert.equal(await retry, 'recovered');
  assert.equal(calls, 2);
});

